using System.Net;
using System.Text.RegularExpressions;
using GzmApp.Tests.Infrastructure;

namespace GzmApp.Tests;

// Level 9: printed materials and student materials (generated by tools/Cards).
public partial class MaterialsTests
{
    public static TheoryData<string> Codes => ScenarioData.Codes;

    private static string Read(params string[] path) => File.ReadAllText(Path.Combine([RepoPaths.Root, .. path]));

    [Theory]
    [MemberData(nameof(Codes))]
    [Trait("Spec", "M-01")]
    [Trait("Poziom", "9")]
    public void Cheat_sheet_has_the_values_of_checkpoints(string code)
    {
        var scenario = ScenarioData.Get(code);
        var row = Row().Matches(Read("print", "sciaga-prowadzacego.html")).Single(m => m.Groups["s"].Value == code).Groups["cells"].Value;
        var values = Cell().Matches(row).Select(m => (Id: m.Groups["id"].Value, Value: WebUtility.HtmlDecode(m.Groups["v"].Value))).ToList();

        Assert.NotEmpty(values);
        Assert.All(values, v => Assert.Equal(scenario.Value(v.Id), v.Value));
        Assert.Contains(values, v => v.Id == "E1.rows");
        Assert.Contains(values, v => v.Id == "E4.title");
    }

    [Theory]
    [MemberData(nameof(Codes))]
    [Trait("Spec", "M-02")]
    [Trait("Poziom", "9")]
    public void Student_materials_have_no_expected_values_and_variant_A_follows_mapping(string code)
    {
        var scenario = ScenarioData.Get(code);
        var prompts = Read("scenarios", code, "prompty.md");
        var student = new[] { prompts, Read("scenarios", code, "karta.md"), Read("print", $"karta-pary-{code}.html") };
        var decisions = Decision().Matches(prompts).ToList();

        Assert.All(student, text => Assert.False(CheckpointId().IsMatch(text) || text.Contains("data-cp", StringComparison.Ordinal)));
        Assert.Equal(4, decisions.Count);
        Assert.All(decisions, d => Assert.True(Variant().Matches(d.Value).Count >= 2, $"{code}: decyzja z mniej niż 2 wariantami"));
        Assert.Contains($"Szukaj w polu `{scenario.Mapping.GetProperty("filter").GetProperty("field").GetString()}`", FirstVariant(decisions[0].Value), StringComparison.Ordinal);
        Assert.All(scenario.Mapping.GetProperty("listFields").EnumerateArray(), f => Assert.Contains($"`{f.GetString()}`", FirstVariant(decisions[1].Value), StringComparison.Ordinal));
        Assert.Contains($"`{scenario.Mapping.GetProperty("statistic").GetProperty("field").GetString()}`", FirstVariant(decisions[2].Value), StringComparison.Ordinal);
    }

    [Fact]
    [Trait("Spec", "M-03")]
    [Trait("Poziom", "9")]
    public void Printed_pages_have_no_placeholders_or_empty_fields()
    {
        var pages = Directory.GetFiles(Path.Combine(RepoPaths.Root, "print"), "*.html");

        Assert.Equal(16, pages.Length);
        Assert.All(pages, p => Assert.False(File.ReadAllText(p).Contains("{{", StringComparison.Ordinal) || EmptyElement().IsMatch(File.ReadAllText(p)), Path.GetFileName(p)));
    }

    [Fact]
    [Trait("Spec", "M-04")]
    [Trait("Poziom", "9")]
    public void Paths_in_PROWADZACY_md_exist()
    {
        var paths = RepoPath().Matches(Read("docs", "PROWADZACY.md")).Select(m => m.Value.Replace('\\', '/').TrimEnd('/').Replace("sNN", "s01")).Distinct().ToList();

        Assert.True(paths.Count > 10, "za mało ścieżek – sprawdź wzorzec");
        Assert.All(paths, p => Assert.True(File.Exists(Path.Combine(RepoPaths.Root, p)) || Directory.Exists(Path.Combine(RepoPaths.Root, p)), p));
    }

    private static string FirstVariant(string decision) => decision.Split("~~~text")[1];

    [GeneratedRegex(@"<tr data-scenario=""(?<s>s\d\d)"">(?<cells>.*?)</tr>", RegexOptions.Singleline)]
    private static partial Regex Row();

    [GeneratedRegex(@"<span data-cp=""(?<id>[^""]+)"">(?<v>.*?)</span>", RegexOptions.Singleline)]
    private static partial Regex Cell();

    [GeneratedRegex(@"\(E\d\.[\w.]+\)")]
    private static partial Regex CheckpointId();

    // One decision: from its heading to the next "### " or "## " heading.
    [GeneratedRegex(@"^### ⏸ Pauza – decyzja \d.*?(?=^##)", RegexOptions.Multiline | RegexOptions.Singleline)]
    private static partial Regex Decision();

    [GeneratedRegex(@"^\*\*[A-Z] – ", RegexOptions.Multiline)]
    private static partial Regex Variant();

    [GeneratedRegex(@"<(li|td)>\s*</\1>")]
    private static partial Regex EmptyElement();

    // Repo paths written in PROWADZACY.md: src/…, tools/…, docs/…, print/…, scenarios/…, data/…, db/…, .kilo/…
    [GeneratedRegex(@"(?<![\w./-])(?:src|tools|docs|print|scenarios|data|db|\.kilo|\.kilocode)(?:[\\/][\w.\-]+)+")]
    private static partial Regex RepoPath();
}
